import { useState } from 'react'
import { DatePicker } from 'moru-ui'

export function DueDate() {
  const [date, setDate] = useState<Date | null>(null)
  return (
    <DatePicker
      label="Due date"
      name="dueDate"
      value={date}
      onValueChange={setDate}
      calendarOptions={{ variant: 'minimal', size: 'md' }}
    />
  )
}
